WITH scored AS (SELECT *, AVG(shipping_fee) OVER w_grp AS running_avg_shipping_fee, MAX(shipping_fee) OVER w_grp AS running_max_shipping_fee, MIN(shipping_fee) OVER w_grp AS running_min_shipping_fee FROM orders WHERE discount > 0.3 WINDOW w_grp AS (PARTITION BY store_id ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN shipping_fee >= 32 THEN 'LARGE' ELSE 'SMALL' END AS shipping_fee_tier, CASE WHEN amount >= 1220 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, status, COUNT(*) AS cnt, PERCENTILE_APPROX(shipping_fee, 0.5) AS shipping_fee_p50, ROUND(AVG(running_max_shipping_fee), 2) AS avg_running_max_shipping_fee, MIN(running_max_shipping_fee) AS min_running_max_shipping_fee FROM scored GROUP BY 1, 2, 3 ORDER BY shipping_fee_tier DESC;
